pub fn format(val: RESPValue, writer: *std.Io.Writer) !void {
            switch (val) {
.SimpleString => |str| {
_ = try writer.writeAll(str);
},
.Error => |str| {
_ = try writer.writeAll(str);
},
.Integer => |int| {
_ = try writer.print("{d}", .{ int });
},
.BulkString => |maybe_str| {
if (maybe_str) |str| {
                _ = &str;
                _ = try writer.writeAll(str);
            } else {
                _ = try writer.writeAll("(nil)");
            }
},
.Array => |array| {
_ = try writer.writeAll("[");
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(array)) |value| {
                _ = &value;
                if ((i > 0)) {
                    _ = try writer.writeAll(", ");
                }
                _ = try value.format(writer);
                i = (i + 1);
            }
            _ = try writer.writeAll("]");
},
.Null => {
_ = try writer.writeAll("(nil)");
},
.Double => |d| {
_ = try writer.print("{d}", .{ d });
},
.Boolean => |b| {
_ = try writer.print("{}", .{ b });
},
.BlobError => |str| {
_ = try writer.print("Error: {s}", .{ str });
},
.VerbatimString => |verbatim| {
_ = try writer.print("{s}:{s}", .{ verbatim.format, verbatim.content });
},
.Map => |entries| {
_ = try writer.writeAll("{");
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(entries)) |entry| {
                _ = &entry;
                if ((i > 0)) {
                    _ = try writer.writeAll(", ");
                }
                _ = try entry.key.format(writer);
                _ = try writer.writeAll(": ");
                _ = try (if (@typeInfo(@TypeOf(entry)) == .@"enum") @intFromEnum(entry) else entry.value).format(writer);
                i = (i + 1);
            }
            _ = try writer.writeAll("}");
},
.Set => |set| {
_ = try writer.writeAll("Set{");
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(set)) |value| {
                _ = &value;
                if ((i > 0)) {
                    _ = try writer.writeAll(", ");
                }
                _ = try value.format(writer);
                i = (i + 1);
            }
            _ = try writer.writeAll("}");
},
.Attribute => |attribute| {
_ = try writer.writeAll("(Attr: ");
            _ = try writer.writeAll("{");
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(attribute.attributes)) |entry| {
                _ = &entry;
                if ((i > 0)) {
                    _ = try writer.writeAll(", ");
                }
                _ = try entry.key.format(writer);
                _ = try writer.writeAll(": ");
                _ = try (if (@typeInfo(@TypeOf(entry)) == .@"enum") @intFromEnum(entry) else entry.value).format(writer);
                i = (i + 1);
            }
            _ = try writer.writeAll("} => ");
            _ = try (if (@typeInfo(@TypeOf(attribute)) == .@"enum") @intFromEnum(attribute) else attribute.value).format(writer);
            _ = try writer.writeAll(")");
},
.Push => |push| {
_ = try writer.print("Push({s}: [", .{ push.kind });
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(push.data)) |value| {
                _ = &value;
                if ((i > 0)) {
                    _ = try writer.writeAll(", ");
                }
                _ = try value.format(writer);
                i = (i + 1);
            }
            _ = try writer.writeAll("])");
},
.BigNumber => |str| {
_ = try writer.print("BigNumber({s})", .{ str });
},
}
    }
