pub const ValkeyReader = struct {
    buffer: []const u8,
    pos: usize = 0,

pub fn init(buffer: []const u8) ValkeyReader {
            return ValkeyReader{ .buffer = buffer };
    }

pub fn readByte(self: *ValkeyReader) RedisError!u8 {
            if ((self.pos >= self.buffer.len)) {
                return error.InvalidResponse;
            }
            const byte = self.buffer[@as(usize, @intCast(self.pos))];
            self.pos = (self.pos + 1);
            return byte;
    }

pub fn readUntilCRLF(self: *ValkeyReader) RedisError![]const u8 {
            const buffer = self.buffer[self.pos..];
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(buffer)) |byte| {
                _ = &byte;
                if ((((byte == 13) and (buffer.len > (i + 1))) and (buffer[@as(usize, @intCast((i + 1)))] == 10))) {
                    const result = buffer[0..i];
                    self.pos = (self.pos + (i + 2));
                    return result;
                }
                i = (i + 1);
            }
            return error.InvalidResponse;
    }

pub fn readInteger(self: *ValkeyReader) RedisError!i64 {
            const str = try self.readUntilCRLF();
            return (blk_catch_0: { break :blk_catch_0 ((std.fmt.parseInt(i64, str, 10)) catch |__ce_0| { _ = &__ce_0; return error.InvalidInteger; }); });
    }

pub fn readDouble(self: *ValkeyReader) RedisError!f64 {
            const str = try self.readUntilCRLF();
            if (std.mem.eql(u8, str, "inf")) {
                return std.math.inf(f64);
            }
            if (std.mem.eql(u8, str, "-inf")) {
                return (-std.math.inf(f64));
            }
            if (std.mem.eql(u8, str, "nan")) {
                return std.math.nan(f64);
            }
            return (blk_catch_1: { break :blk_catch_1 ((std.fmt.parseFloat(f64, str)) catch |__ce_1| { _ = &__ce_1; return error.InvalidDouble; }); });
    }

pub fn readBoolean(self: *ValkeyReader) RedisError!bool {
            const str = try self.readUntilCRLF();
            if ((str.len != 1)) {
                return error.InvalidBoolean;
            }
            return (switch (str[0]) {
't' => true,
'f' => false,
else => error.InvalidBoolean,
});
    }

pub fn readVerbatimString(self: *ValkeyReader, allocator: std.mem.Allocator) RedisError!VerbatimString {
            const len = try self.readInteger();
            if ((len < 0)) {
                return error.InvalidVerbatimString;
            }
            const ulen = (if (comptime @typeInfo(@TypeOf(len)) == .@"enum") cp_cast_int(usize, @intFromEnum(len)) else cp_cast_int(usize, len));
            if (((self.pos + ulen) > self.buffer.len)) {
                return error.InvalidVerbatimString;
            }
            const content_with_format = self.buffer[self.pos..(self.pos + ulen)];
            self.pos = (self.pos + ulen);
            const crlf = try self.readUntilCRLF();
            if ((crlf.len != 0)) {
